        const u = edgeU[i];
        const v = edgeV[i];
        const t = edgeT[i];
        pairType[curOffset[u]++] = t;
        pairType[curOffset[v]++] = t;
    }

    // Now for each vertex u, sort types and remove duplicates
    // Also assign a nodeId for each unique (u, t)
    const uniqueTypeStart = new Int32Array(N + 2);
    const uniqueTypeCount = new Int32Array(N + 1);

