        tempTypes.subarray(0, count).sort();

        // Write unique back to pairType starting at totalUniquePairs
        uniqueTypeStart[u] = totalUniquePairs;
        let uCount = 0;
        for (let i = 0; i < count; i++) {
            if (i === 0 || tempTypes[i] !== tempTypes[i - 1]) {
                pairType[totalUniquePairs + uCount] = tempTypes[i];
                uCount++;
            }
        }
        uniqueTypeCount[u] = uCount;
        totalUniquePairs += uCount;
