    // neutral node for vertex u is u (1-indexed, 1 to N)
    // unique pair at pairIndex gets ID: N + 1 + pairIndex
    function getNodeId(u, t) {
        const start = uniqueTypeStart[u];
        const count = uniqueTypeCount[u];
        // Binary search for t in pairType[start ... start + count - 1]
        let low = 0, high = count - 1;
        while (low <= high) {
            const mid = (low + high) >> 1;
            const val = pairType[start + mid];
            if (val === t) {
                return N + 1 + (start + mid);
            } else if (val < t) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return -1;
    }

