    // Total edges:
    // For each unique (u, t):
    //   u -> (u, t) with weight P[t]
    //   (u, t) -> u with weight 0
    // For each original edge (u, v, t):
    //   (u, t) -> (v, t) with weight 0
    //   (v, t) -> (u, t) with weight 0
    const maxGraphEdges = 2 * totalUniquePairs + 2 * M;

    const gHead = new Int32Array(numNodes + 1).fill(-1);
    const gTo = new Int32Array(maxGraphEdges);
    const gWeight = new Int32Array(maxGraphEdges);
    const gNext = new Int32Array(maxGraphEdges);
    let edgeCount = 0;

