        gTo[edgeCount] = v;
        gWeight[edgeCount] = w;
        gNext[edgeCount] = gHead[u];
        gHead[u] = edgeCount++;
    }

    // Add edges between neutral nodes and (u, t)
    for (let u = 1; u <= N; u++) {
        const start = uniqueTypeStart[u];
        const count = uniqueTypeCount[u];
        for (let i = 0; i < count; i++) {
            const t = pairType[start + i];
            const nodeId = N + 1 + (start + i);
            addEdge(u, nodeId, P[t]);
            addEdge(nodeId, u, 0);
        }
    }

    // Add edges for each original transport connection
    for (let i = 0; i < M; i++) {
        const u = edgeU[i];
        const v = edgeV[i];
        const t = edgeT[i];
        const nodeU = getNodeId(u, t);
        const nodeV = getNodeId(v, t);
        addEdge(nodeU, nodeV, 0);
        addEdge(nodeV, nodeU, 0);
    }

    // Dijkstra
    const INF = 1073741823; // ~10^9
    const dist = new Int32Array(numNodes + 1).fill(INF);

    // Min-Heap implementation
    let heapCapacity = 65536;
    let heapSize = 0;
    let heapDist = new Int32Array(heapCapacity);
    let heapNode = new Int32Array(heapCapacity);

    function pushHeap(d, u) {
        if (heapSize === heapCapacity) {
            heapCapacity *= 2;
            const newHeapDist = new Int32Array(heapCapacity);
            const newHeapNode = new Int32Array(heapCapacity);
            newHeapDist.set(heapDist);
            newHeapNode.set(heapNode);
            heapDist = newHeapDist;
            heapNode = newHeapNode;
        }
        let i = heapSize++;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heapDist[p] <= d) break;
            heapDist[i] = heapDist[p];
            heapNode[i] = heapNode[p];
            i = p;
        }
        heapDist[i] = d;
        heapNode[i] = u;
    }

    function popHeap() {
        const resU = heapNode[0];
        const resD = heapDist[0];
        heapSize--;
        if (heapSize > 0) {
            const lastD = heapDist[heapSize];
            const lastU = heapNode[heapSize];
            let i = 0;
            const half = heapSize >> 1;
            while (i < half) {
                let left = (i << 1) + 1;
                const right = left + 1;
                if (right < heapSize && heapDist[right] < heapDist[left]) {
                    left = right;
                }
                if (lastD <= heapDist[left]) break;
                heapDist[i] = heapDist[left];
                heapNode[i] = heapNode[left];
                i = left;
            }
            heapDist[i] = lastD;
            heapNode[i] = lastU;
        }
        return { d: resD, u: resU };
    }

    dist[A] = 0;
    pushHeap(0, A);

    while (heapSize > 0) {
        const top = popHeap();
        const d = top.d;
        const u = top.u;

        if (d > dist[u]) continue;
        if (u === B) break;

        for (let e = gHead[u]; e !== -1; e = gNext[e]) {
            const v = gTo[e];
            const w = gWeight[e];
            const nd = d + w;
            if (nd < dist[v]) {
                dist[v] = nd;
                pushHeap(nd, v);
            }
        }
    }

    if (dist[B] === INF) {
        console.log(-1);
    } else {
        console.log(dist[B]);
    }
}

